CREATE TEMPORARY TABLE `_coa_tw_new` (`entry` INT UNSIGNED NOT NULL PRIMARY KEY) ENGINE=InnoDB;
DELETE FROM `_coa_tw_new` WHERE 1 = 0;
INSERT INTO `_coa_tw_new` SELECT `_owner` FROM `_coa_tw_0`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_template_model` AS `t` ON `t`.`CreatureID` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_template_spell` AS `t` ON `t`.`CreatureID` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_template_addon` AS `t` ON `t`.`entry` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_template_resistance` AS `t` ON `t`.`CreatureID` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_template_movement` AS `t` ON `t`.`CreatureId` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_equip_template` AS `t` ON `t`.`CreatureID` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_text` AS `t` ON `t`.`CreatureID` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_text_locale` AS `t` ON `t`.`CreatureID` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_template` AS `t` ON `t`.`entry` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_loot_template` AS `t` ON `t`.`Entry` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_template_locale` AS `t` ON `t`.`entry` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_onkill_reputation` AS `t` ON `t`.`creature_id` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_questitem` AS `t` ON `t`.`CreatureEntry` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_summon_groups` AS `t` ON `t`.`summonerId` = `g`.`entry` AND
    `t`.`summonerType` = 0;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_queststarter` AS `t` ON `t`.`id` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_questender` AS `t` ON `t`.`id` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `game_event_creature_quest` AS `t` ON `t`.`id` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `npc_vendor` AS `t` ON `t`.`entry` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `npc_spellclick_spells` AS `t` ON `t`.`npc_entry` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `creature_template` AS `t` ON `t`.`lootid` = `g`.`entry`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `conditions` AS `t` ON (`t`.`SourceTypeOrReferenceId` = 1 AND
    `t`.`SourceGroup` = `g`.`entry`) OR (`t`.`SourceTypeOrReferenceId` = 22 AND `t`.`SourceEntry` = `g`.`entry` AND
    `t`.`SourceId` = 0);
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `smart_scripts` AS `t` ON `t`.`entryorguid` = `g`.`entry` AND
    `t`.`source_type` = 0;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `_coa_tw_9` AS `s` ON `s`.`_owner` = `g`.`entry` INNER JOIN
    `smart_scripts` AS `t` ON `t`.`entryorguid` = `s`.`entryorguid` AND `t`.`source_type` = `s`.`source_type`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `_coa_tw_9` AS `s` ON `s`.`_owner` = `g`.`entry` INNER JOIN `conditions`
    AS `t` ON `t`.`SourceTypeOrReferenceId` = 22 AND `t`.`SourceEntry` = `s`.`entryorguid` AND `t`.`SourceId` =
    `s`.`source_type`;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `_coa_tw_11` AS `s` ON `s`.`_owner` = `g`.`entry` LEFT JOIN
    `item_template` AS `i` ON `i`.`entry` = `s`.`Item` WHERE `i`.`entry` IS NULL OR `i`.`class` = 12 OR `i`.`Bonding` =
    4 OR `i`.`startquest` <> 0;
DELETE `g` FROM `_coa_tw_new` AS `g` INNER JOIN `_coa_tw_11` AS `s` ON `s`.`_owner` = `g`.`entry` INNER JOIN
    `quest_template` AS `q` ON `s`.`Item` IN (`q`.`RequiredItemId1`, `q`.`RequiredItemId2`, `q`.`RequiredItemId3`,
    `q`.`RequiredItemId4`, `q`.`RequiredItemId5`, `q`.`RequiredItemId6`, `q`.`ItemDrop1`, `q`.`ItemDrop2`,
    `q`.`ItemDrop3`, `q`.`ItemDrop4`);
CREATE TEMPORARY TABLE `_coa_tw_owned` ENGINE=InnoDB AS SELECT DISTINCT `s`.`entry` FROM `_coa_tw_0` AS `s` INNER JOIN
